package portfolio.week07;
import javafx.application.Application; import javafx.scene.Scene; import javafx.scene.control.*; import javafx.scene.input.KeyCode; import javafx.scene.layout.VBox; import javafx.stage.Stage;
public class EventDemo extends Application { public void start(Stage s){ Label log=new Label("Press a key or click the button"); Button b=new Button("Fire custom event"); VBox root=new VBox(12,b,log); root.setOnKeyPressed(e->{ if(e.getCode()==KeyCode.ESCAPE){e.consume(); log.setText("Escape was filtered at the parent");} }); b.setOnAction(e->log.setText("Action handler received the click")); root.setFocusTraversable(true); Scene scene=new Scene(root,420,180); s.setScene(scene); s.show(); root.requestFocus(); } public static void main(String[] a){launch(a);} }
